{"content": "1|//! Local build artefact observation — binds `BuildArtefactObservationPort` to the
2|//! host's own `/var/lib/cynic/checkouts` tree (no SSH). It reads `/proc`-less
3|//! substrate via `capture_command` (lsblk/df/du/git) and reuses the pure
4|//! `parse_checkout_list` / `parse_df_pressure` / `build_gc_plan` parsers shared
5|//! with the remote adapter so the two never diverge.
6|
7|use std::fs;
8|use std::os::unix::fs::MetadataExt;
9|use std::path::Path;
10|use std::time::{SystemTime, UNIX_EPOCH};
11|
12|use chrono::{DateTime, Utc};
13|
14|use crate::domain::build_artefact::port::{
15|    BuildArtefactGcExecutionPort, BuildArtefactObservationPort,
16|};
17|use crate::domain::build_artefact::probe::{build_gc_plan, parse_checkout_list, parse_df_pressure};
18|use crate::domain::disk::probe::{parse_df_filesystems, parse_lsblk_disks};
19|use crate::process_observation::capture_command;
20|use cynic_protocol::build_artefact::{
21|    BUILD_ARTEFACT_GC_RESULT_SCHEMA, BUILD_ARTEFACT_REPORT_SCHEMA, BuildArtefactGcPlan,
22|    BuildArtefactGcResult, BuildArtefactGcStepExecution, BuildArtefactReport,
23|};
24|use cynic_protocol::disk::bytes_to_human;
25|
26|const CHECKOUTS_BASE: &str = "/var/lib/cynic/checkouts";
27|
28|#[derive(Debug, Default, Clone, Copy)]
29|pub struct LocalBuildArtefactAdapter;
30|
31|impl BuildArtefactObservationPort for LocalBuildArtefactAdapter {
32|    fn observe_build_artefacts(&self) -> Result<BuildArtefactReport, String> {
33|        let timestamp = DateTime::<Utc>::from(SystemTime::now())
34|            .format("%Y-%m-%dT%H:%M:%SZ")
35|            .to_string();
36|
37|        let physical_disks = observe_physical_disks();
38|        let filesystems = observe_filesystems();
39|        let (checkouts_raw, remote_shas) = observe_checkouts_raw();
40|        let checkouts = parse_checkout_list(&checkouts_raw, &remote_shas);
41|        let total_checkout_bytes: u64 = checkouts.iter().map(|c| c.size_bytes).sum();
42|        let total_checkout_human = bytes_to_human(total_checkout_bytes);
43|        // target/ size is rolled into checkouts for now - separate once builder exposes it
44|        let df_out = capture_command("df", &["-k", CHECKOUTS_BASE])
45|            .ok()
46|            .filter(|c| c.success)
47|            .map(|c| c.stdout)
48|            .or_else(|| {
49|                capture_command("df", &["-k", "/"])
50|                    .ok()
51|                    .filter(|c| c.success)
52|                    .map(|c| c.stdout)
53|            })
54|            .unwrap_or_default();
55|        let root_owned = checkouts.iter().filter(|c| c.is_root_owned).count();
56|        let pressure = parse_df_pressure(&df_out, root_owned);
57|
58|        // residual unknowns: missing base or unparsable lsblk
59|        let mut residual_unknowns = Vec::new();
60|        if !Path::new(CHECKOUTS_BASE).exists() {
61|            residual_unknowns.push(format!("checkouts_base_missing:{CHECKOUTS_BASE}"));
62|        }
63|        if physical_disks.is_empty() {
64|            // not fatal - may be container without lsblk
65|            residual_unknowns.push("physical_disks_unknown".to_string());
66|        }
67|
68|        Ok(BuildArtefactReport {
69|            schema: BUILD_ARTEFACT_REPORT_SCHEMA.to_string(),
70|            timestamp,
71|            physical_disks,
72|            filesystems,
73|            checkouts,
74|            total_checkout_bytes,
75|            total_checkout_human,
76|            target_bytes: 0,
77|            target_human: "0B".to_string(),
78|            pressure,
79|            residual_unknowns,
80|        })
81|    }
82|
83|    fn plan_gc(&self, report: &BuildArtefactReport) -> BuildArtefactGcPlan {
84|        build_gc_plan(report)
85|    }
86|}
87|
88|impl BuildArtefactGcExecutionPort for LocalBuildArtefactAdapter {
89|    fn execute_gc(&self, plan: &BuildArtefactGcPlan) -> BuildArtefactGcResult {
90|        let timestamp = DateTime::<Utc>::from(SystemTime::now())
91|            .format("%Y-%m-%dT%H:%M:%SZ")
92|            .to_string();
93|        let mut items_executed = Vec::new();
94|        let mut total_reclaimed_bytes = 0u64;
95|        let mut success = true;
96|
97|        for item in &plan.items {
98|            let exec = execute_gc_item(item);
99|            if exec.success {
100|                total_reclaimed_bytes += item.size_bytes;
101|            } else {
102|                success = false;
103|            }
104|            items_executed.push(exec);
105|        }
106|
107|        BuildArtefactGcResult {
108|            schema: BUILD_ARTEFACT_GC_RESULT_SCHEMA.to_string(),
109|            timestamp,
110|            success,
111|            items_executed,
112|            total_reclaimed_bytes,
113|            total_reclaimed_human: bytes_to_human(total_reclaimed_bytes),
114|        }
115|    }
116|}
117|
118|fn observe_physical_disks() -> Vec<cynic_protocol::disk::PhysicalDisk> {
119|    let out = capture_command(
120|        "lsblk",
121|        &[
122|            "-b",
123|            "-J",
124|            "-o",
125|            "NAME,SIZE,TYPE,ROTA,VENDOR,MODEL,SERIAL,WWN,MOUNTPOINT",
126|        ],
127|    );
128|    match out {
129|        Ok(c) if c.success => parse_lsblk_disks(&c.stdout),
130|        _ => Vec::new(),
131|    }
132|}
133|
134|fn observe_filesystems() -> Vec<cynic_protocol::disk::DiskFilesystem> {
135|    let out = capture_command(
136|        "df",
137|        &["-h", "--output=source,fstype,size,used,avail,pcent,target"],
138|    );
139|    let stdout = match out {
140|        Ok(c) if c.success => c.stdout,
141|        _ => {
142|            let fb = capture_command("df", &["-h"]);
143|            match fb {
144|                Ok(c) if c.success => c.stdout,
145|                _ => return Vec::new(),
146|            }
147|        }
148|    };
149|    parse_df_filesystems(&stdout)
150|}
151|
152|fn observe_checkouts_raw() -> (String, Vec<String>) {
153|    // Collect a pipe of "<path>|<sha>|<size>|<uid:gid>|<mtime_secs>|<remote 0/1>"
154|    // then feed to pure parse_checkout_list. Remote shas come from one batch ls-remote.
155|    let remote_shas = fetch_remote_shas();
156|    let mut lines = Vec::new();
157|    let entries = fs::read_dir(CHECKOUTS_BASE).ok();
158|    let Some(entries) = entries else {
159|        return (String::new(), remote_shas);
160|    };
161|    for entry in entries.flatten() {
162|        let path = entry.path();
163|        if !path.is_dir() {
164|            continue;
165|        }
166|        let path_str = path.display().to_string();
167|        let sha = git_sha(&path).unwrap_or_else(|| {
168|            path.file_name()
169|                .and_then(|n| n.to_str())
170|                .unwrap_or("unknown")
171|                .to_string()
172|        });
173|        let (size_bytes, uid, gid, mtime_secs) = file_meta(&path);
174|        let remote_exists = if remote_shas.contains(&sha) { "1" } else { "0" };
175|        // if remote_shas empty (no origin), leave flag but pure parser will fallback to list check
176|        let line =
177|            format!("{path_str}|{sha}|{size_bytes}|{uid}:{gid}|{mtime_secs}|{remote_exists}");
178|        lines.push(line);
179|    }
180|    (lines.join("\n"), remote_shas)
181|}
182|
183|fn git_sha(path: &Path) -> Option<String> {
184|    let out = capture_command(
185|        "git",
186|        &["-C", &path.display().to_string(), "rev-parse", "HEAD"],
187|    )
188|    .ok()?;
189|    if out.success && !out.stdout.is_empty() {
190|        Some(out.stdout.trim().to_string())
191|    } else {
192|        None
193|    }
194|}
195|
196|fn file_meta(path: &Path) -> (u64, u32, u32, u64) {
197|    let meta = fs::metadata(path).ok();
198|    let (uid, gid) = meta
199|        .as_ref()
200|        .map(|m| (m.uid(), m.gid()))
201|        .unwrap_or((999, 990));
202|    let mtime_secs = meta
203|        .as_ref()
204|        .and_then(|m| m.modified().ok())
205|        .and_then(|t| t.duration_since(UNIX_EPOCH).ok())
206|        .map(|d| {
207|            (SystemTime::now()
208|                .duration_since(UNIX_EPOCH)
209|                .unwrap_or_default()
210|                .as_secs()
211|                .saturating_sub(d.as_secs()))
212|        })
213|        .unwrap_or(0);
214|    // size via du -sb if available, else walk
215|    let size_bytes = capture_command("du", &["-sb", &path.display().to_string()])
216|        .ok()
217|        .and_then(|c| {
218|            if c.success {
219|                c.stdout.split_whitespace().next()?.parse::<u64>().ok()
220|            } else {
221|                None
222|            }
223|        })
224|        .unwrap_or_else(|| walk_size(path));
225|    (size_bytes, uid, gid, mtime_secs)
226|}
227|
228|fn walk_size(path: &Path) -> u64 {
229|    let mut total = 0u64;
230|    let mut stack = vec![path.to_path_buf()];
231|    while let Some(cur) = stack.pop() {
232|        if let Ok(entries) = fs::read_dir(&cur) {
233|            for e in entries.flatten() {
234|                let p = e.path();
235|                if p.is_symlink() {
236|                    continue;
237|                }
238|                if p.is_dir() {
239|                    stack.push(p);
240|                } else if let Ok(m) = e.metadata() {
241|                    total += m.len();
242|                }
243|            }
244|        }
245|    }
246|    total
247|}
248|
249|fn fetch_remote_shas() -> Vec<String> {
250|    // Try a known checkout with origin first, then bare ls-remote
251|    for base in [CHECKOUTS_BASE, "."] {
252|        let out = if base == "." {
253|            capture_command("git", &["ls-remote", "origin"]).ok()
254|        } else {
255|            // find first checkout that is a git repo
256|            let mut found = None;
257|            if let Ok(entries) = fs::read_dir(base) {
258|                for e in entries.flatten() {
259|                    let p = e.path().join(".git");
260|                    if p.exists() {
261|                        found = Some(e.path().display().to_string());
262|                        break;
263|                    }
264|                }
265|            }
266|            if let Some(path) = found {
267|                capture_command("git", &["-C", &path, "ls-remote", "origin"]).ok()
268|            } else {
269|                capture_command("git", &["ls-remote", "origin"]).ok()
270|            }
271|        };
272|        if let Some(c) = out {
273|            if c.success && !c.stdout.trim().is_empty() {
274|                return c
275|                    .stdout
276|                    .lines()
277|                    .filter_map(|l| l.split_whitespace().next().map(|s| s.to_string()))
278|                    .collect();
279|            }
280|        }
281|    }
282|    Vec::new()
283|}
284|
285|fn execute_gc_item(
286|    item: &cynic_protocol::build_artefact::BuildArtefactGcItem,
287|) -> BuildArtefactGcStepExecution {
288|    if item.argv.is_empty() {
289|        return BuildArtefactGcStepExecution {
290|            item_id: item.id.clone(),
291|            label: item.label.clone(),
292|            success: false,
293|            exit_code: None,
294|            stdout_tail: String::new(),
295|            stderr_tail: "empty argv".to_string(),
296|        };
297|    }
298|    let (bin, args): (&str, Vec<&str>) = if item.requires_privilege {
299|        ("sudo", item.argv.iter().map(|s| s.as_str()).collect())
300|    } else {
301|        (
302|            item.argv[0].as_str(),
303|            item.argv[1..].iter().map(|s| s.as_str()).collect(),
304|        )
305|    };
306|    match capture_command(bin, &args) {
307|        Ok(o) => BuildArtefactGcStepExecution {
308|            item_id: item.id.clone(),
309|            label: item.label.clone(),
310|            success: o.success,
311|            exit_code: o.exit_code,
312|            stdout_tail: tail(&o.stdout, 800),
313|            stderr_tail: tail(&o.stderr, 800),
314|        },
315|        Err(e) => BuildArtefactGcStepExecution {
316|            item_id: item.id.clone(),
317|            label: item.label.clone(),
318|            success: false,
319|            exit_code: None,
320|            stdout_tail: String::new(),
321|            stderr_tail: e.to_string(),
322|        },
323|    }
324|}
325|
326|fn tail(s: &str, n: usize) -> String {
327|    if s.len() <= n {
328|        s.to_string()
329|    } else {
330|        s[s.len() - n..].to_string()
331|    }
332|}
