{"content": "1|//! Pure parsers for build artefact observation (no I/O).
2|//! 4-layer substrate mining: physical -> volume -> usage (checkouts) -> pressure.
3|
4|use cynic_protocol::build_artefact::{
5|    BUILD_ARTEFACT_GC_PLAN_SCHEMA, BuildArtefactGcItem, BuildArtefactGcPlan, BuildArtefactReport,
6|    CheckoutEntry, DiskPressure,
7|};
8|use cynic_protocol::disk::bytes_to_human;
9|
10|/// Parse `ls -1 /var/lib/cynic/checkouts` + `du -sb` + `stat` lines into CheckoutEntry.
11|/// Each line: "<path>|<sha>|<size_bytes>|<uid>:<gid>|<mtime_secs>|<remote_exists 0/1>"
12|/// Pure, no FS touch.
13|pub fn parse_checkout_list(raw: &str, remote_shas: &[String]) -> Vec<CheckoutEntry> {
14|    let mut out = Vec::new();
15|    for line in raw.lines() {
16|        let line = line.trim();
17|        if line.is_empty() {
18|            continue;
19|        }
20|        let parts: Vec<&str> = line.split('|').collect();
21|        if parts.len() < 6 {
22|            continue;
23|        }
24|        let path = parts[0].to_string();
25|        let sha = parts[1].to_string();
26|        let size_bytes: u64 = parts[2].parse().unwrap_or(0);
27|        let owner: Vec<&str> = parts[3].split(':').collect();
28|        let uid: u32 = owner.first().and_then(|v| v.parse().ok()).unwrap_or(999);
29|        let gid: u32 = owner.get(1).and_then(|v| v.parse().ok()).unwrap_or(990);
30|        let age_secs: Option<u64> = parts[4].parse().ok();
31|        let remote_flag: Option<bool> = match parts[5] {
32|            "1" => Some(true),
33|            "0" => Some(false),
34|            _ => None,
35|        };
36|        let is_orphan = match remote_flag {
37|            Some(exists) => !exists,
38|            None => {
39|                // No remote fetch available (unknown) -> conservative, not orphan
40|                if remote_shas.is_empty() {
41|                    false
42|                } else {
43|                    !remote_shas.contains(&sha)
44|                }
45|            }
46|        };
47|        let branch = path.rsplit('/').next().unwrap_or(&path).to_string();
48|        out.push(CheckoutEntry {
49|            path: path.clone(),
50|            sha: sha.clone(),
51|            branch,
52|            age_secs,
53|            size_bytes,
54|            size_human: bytes_to_human(size_bytes),
55|            owner_uid: uid,
56|            owner_gid: gid,
57|            is_orphan,
58|            is_root_owned: uid == 0,
59|            remote_exists: remote_flag,
60|        });
61|    }
62|    out.sort_by(|a, b| b.size_bytes.cmp(&a.size_bytes));
63|    out
64|}
65|
66|/// Parse `df -k /var/lib/cynic` avail/use% into DiskPressure. Pure.
67|pub fn parse_df_pressure(df_output: &str, root_owned_count: usize) -> DiskPressure {
68|    let mut avail_bytes = 0u64;
69|    let mut use_pct = 0u8;
70|    for line in df_output.lines().skip(1) {
71|        let parts: Vec<&str> = line.split_whitespace().collect();
72|        if parts.len() >= 4 {
73|            if let Ok(kb) = parts[3].parse::<u64>() {
74|                avail_bytes = kb * 1024;
75|            }
76|            if let Some(pct_str) = parts.get(4) {
77|                if let Ok(pct) = pct_str.trim_end_matches('%').parse::<u8>() {
78|                    use_pct = pct;
79|                }
80|            }
81|            break;
82|        }
83|    }
84|    DiskPressure {
85|        avail_bytes,
86|        avail_human: bytes_to_human(avail_bytes),
87|        use_pct,
88|        is_pressured: use_pct >= 80 || avail_bytes < 5 * 1024 * 1024 * 1024,
89|        root_owned_target_count: root_owned_count,
90|    }
91|}
92|
93|/// Pure GC plan: orphan or old are reclaimable; root-owned is extra signal, not sole reason.
94|/// Protects live recent checkouts (is_orphan=false and age<48h) even if root-owned.
95|pub fn build_gc_plan(report: &BuildArtefactReport) -> BuildArtefactGcPlan {
96|    let mut items = Vec::new();
97|    let mut total = 0u64;
98|    for co in &report.checkouts {
99|        let mut reasons = Vec::new();
100|        if co.is_orphan {
101|            reasons.push("orphan(no remote)".to_string());
102|        }
103|        let is_old = co.age_secs.map(|a| a > 48 * 3600).unwrap_or(false);
104|        if is_old {
105|            reasons.push(format!("age {}h", co.age_secs.unwrap() / 3600));
106|        }
107|        // Reclaimable iff orphan or old; root-owned alone is not reclaimable (protects live recent)
108|        if reasons.is_empty() {
109|            continue;
110|        }
111|        // Append root-owned as extra qualifier when reclaimable
112|        if co.is_root_owned {
113|            reasons.push("root-owned".to_string());
114|        }
115|        let reason = reasons.join("+");
116|        let id = format!("checkout:{}", co.sha.chars().take(8).collect::<String>());
117|        let label = format!("{} ({})", co.path, reason);
118|        total += co.size_bytes;
119|        items.push(BuildArtefactGcItem {
120|            id,
121|            label,
122|            path: co.path.clone(),
123|            size_human: co.size_human.clone(),
124|            size_bytes: co.size_bytes,
125|            reason,
126|            requires_privilege: co.is_root_owned,
127|            argv: vec!["rm".to_string(), "-rf".to_string(), co.path.clone()],
128|        });
129|    }
130|    BuildArtefactGcPlan {
131|        schema: BUILD_ARTEFACT_GC_PLAN_SCHEMA.to_string(),
132|        items,
133|        total_reclaimable_bytes: total,
134|        total_reclaimable_human: bytes_to_human(total),
135|    }
136|}
137|
