4|
5|/// Stale threshold is policy, not stored bool — 48h for checkouts, 30d for branches.
6|pub const BRANCH_STALE_AFTER_SECS: u64 = 30 * 24 * 3600;
7|
8|#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
9|pub struct BranchGraph {
10|    pub schema: String,
11|    pub root: String,
12|    pub root_commit: String,
13|    pub nodes: Vec<BranchNode>,
14|}
15|
16|#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
17|pub struct BranchNode {
18|    pub name: String,
19|    pub commit: String,
20|    pub parent: Option<String>,
21|    pub has_upstream: bool,
22|    pub last_commit_unix_s: Option<u64>,
23|}
24|
25|pub fn is_root(node: &BranchNode) -> bool {
26|    node.parent.is_none()
27|}
28|
29|pub fn is_stale(node: &BranchNode, now_unix_s: u64) -> bool {
30|    match node.last_commit_unix_s {
31|        Some(ts) => now_unix_s.saturating_sub(ts) > BRANCH_STALE_AFTER_SECS,
32|        None => true,
33|    }
34|}
35|
36|/// Pure port for branch observation.
37|pub trait BranchObservationPort {
38|    fn observe(&self) -> Result<BranchGraph, String>;
39|}
