249|fn fetch_remote_shas() -> Vec<String> {
250|    // Try a known checkout with origin first, then bare ls-remote
251|    for base in [CHECKOUTS_BASE, "."] {
252|        let out = if base == "." {
253|            capture_command("git", &["ls-remote", "origin"]).ok()
254|        } else {
255|            // find first checkout that is a git repo
256|            let mut found = None;
257|            if let Ok(entries) = fs::read_dir(base) {
258|                for e in entries.flatten() {
259|                    let p = e.path().join(".git");
260|                    if p.exists() {
261|                        found = Some(e.path().display().to_string());
262|                        break;
263|                    }
264|                }
265|            }
266|            if let Some(path) = found {
267|                capture_command("git", &["-C", &path, "ls-remote", "origin"]).ok()
268|            } else {
269|                capture_command("git", &["ls-remote", "origin"]).ok()
270|            }
271|        };
272|        if let Some(c) = out {
273|            if c.success && !c.stdout.trim().is_empty() {
274|                return c
275|                    .stdout
276|                    .lines()
277|                    .filter_map(|l| l.split_whitespace().next().map(|s| s.to_string()))
278|                    .collect();
279|            }
280|        }
