286|    item: &cynic_protocol::build_artefact::BuildArtefactGcItem,
287|) -> BuildArtefactGcStepExecution {
288|    if item.argv.is_empty() {
289|        return BuildArtefactGcStepExecution {
290|            item_id: item.id.clone(),
291|            label: item.label.clone(),
292|            success: false,
293|            exit_code: None,
294|            stdout_tail: String::new(),
295|            stderr_tail: "empty argv".to_string(),
296|        };
297|    }
298|    let (bin, args): (&str, Vec<&str>) = if item.requires_privilege {
299|        ("sudo", item.argv.iter().map(|s| s.as_str()).collect())
300|    } else {
301|        (
302|            item.argv[0].as_str(),
303|            item.argv[1..].iter().map(|s| s.as_str()).collect(),
304|        )
305|    };
306|    match capture_command(bin, &args) {
307|        Ok(o) => BuildArtefactGcStepExecution {
308|            item_id: item.id.clone(),
309|            label: item.label.clone(),
310|            success: o.success,
311|            exit_code: o.exit_code,
312|            stdout_tail: tail(&o.stdout, 800),
313|            stderr_tail: tail(&o.stderr, 800),
314|        },
315|        Err(e) => BuildArtefactGcStepExecution {
316|            item_id: item.id.clone(),
317|            label: item.label.clone(),
318|            success: false,
319|            exit_code: None,
320|            stdout_tail: String::new(),
321|            stderr_tail: e.to_string(),
322|        },
323|    }
