{"content": "1|//! Pure CPU parsers (no I/O). Each takes a captured substrate string and
2|//! returns typed layers of `cynic_protocol::cpu`. Unit tests are deterministic
3|//! fixtures, not host reads.
4|
5|use crate::domain::cpu::{CpuPhysical, CpuPressure, CpuUsage, CpuVolume};
6|
7|/// Parse `/proc/cpuinfo` into the physical + volume layer pieces.
8|///
9|/// `/proc/cpuinfo` repeats a `processor : N` block per logical CPU; we count
10|/// blocks for `logical_cpus`, and take `model name` / `cpu cores` from the
11|/// first block. Frequency (bogomips) is observed but treated as auxiliary
12|/// evidence (not an authority for core count).
13|pub fn parse_cpuinfo(text: &str) -> (CpuPhysical, CpuVolume, Vec<String>) {
14|    let mut unknowns: Vec<String> = Vec::new();
15|    let mut model_name = String::from("unknown");
16|    let mut logical_cpus = 0usize;
17|    let mut cores: Option<usize> = None;
18|    let mut sockets: Option<usize> = None;
19|    let mut bogomips: Option<f64> = None;
20|
21|    let mut in_first_block = true;
22|    for line in text.lines() {
23|        let line = line.trim();
24|        if line.is_empty() {
25|            // blank line separates cpuinfo "processor" blocks.
26|            in_first_block = false;
27|            continue;
28|        }
29|        // Only count "processor :" entries as logical CPU markers; the
30|        // header field repeats once per block.
31|        if let Some((key, value)) = line.split_once(':') {
32|            let key = key.trim();
33|            let value = value.trim();
34|            match key {
35|                "processor" if in_first_block => {
36|                    // logical_cpus is counted below via blocks.
37|                }
38|                "processor" => {
39|                    logical_cpus += 1;
40|                }
41|                "model name" if model_name == "unknown" => {
42|                    model_name = value.to_string();
43|                }
44|                "cpu cores" => {
45|                    cores = value.parse::<usize>().ok();
46|                }
47|                "physical id" => {
48|                    // physical id increments per socket; track max+1.
49|                    if let Ok(id) = value.parse::<usize>() {
50|                        sockets = Some(sockets.map_or(id + 1, |s: usize| s.max(id + 1)));
51|                    }
52|                }
53|                "bogomips" => {
54|                    bogomips = value.parse::<f64>().ok();
55|                }
56|                _ => {}
57|            }
58|        }
59|    }
60|    // The first CPU has processor=0 counted as a block too — recompute count
61|    // robustly: number of "processor :" lines.
62|    let re_count = text
63|        .match_indices("processor\t:")
64|        .count()
65|        .max(text.match_indices("processor :").count());
66|    if re_count != 0 {
67|        logical_cpus = re_count;
68|    }
69|    if cores.is_none() {
70|        unknowns.push("cpu_cores_not_observed".to_string());
71|    }
72|    if sockets.is_none() {
73|        unknowns.push("sockets_not_observed".to_string());
74|    }
75|
76|    let physical = CpuPhysical {
77|        model_name,
78|        logical_cpus,
79|        cores,
80|        sockets,
81|        max_bogomips_or_hz: bogomips,
82|    };
83|    let volume = CpuVolume {
84|        governor: None,
85|        isolated_mask: None,
86|        online_cpus: logical_cpus,
87|        possible_cpus: logical_cpus,
88|    };
89|    (physical, volume, unknowns)
90|}
91|
92|/// Parse `/proc/pressure/cpu` (only the `some` line; cpu PSI has no `full`).
93|pub fn parse_pressure_cpu(text: &str) -> Option<CpuPressure> {
94|    let mut some_avg10: Option<f64> = None;
95|    let mut softirq_steal: Option<u64> = None;
96|    for line in text.lines() {
97|        let line = line.trim();
98|        if let Some(rest) = line.strip_prefix("some ") {
99|            some_avg10 = rest
100|                .split_whitespace()
101|                .find_map(|t| t.strip_prefix("avg10=").and_then(|s| s.parse::<f64>().ok()));
102|            softirq_steal = rest
103|                .split_whitespace()
104|                .find_map(|t| t.strip_prefix("total=").and_then(|s| s.parse::<u64>().ok()));
105|        }
106|    }
107|    if some_avg10.is_none() && softirq_steal.is_none() {
108|        return None;
109|    }
110|    Some(CpuPressure {
111|        some_avg10,
112|        // cpu PSI has no "full" line.
113|        full_avg10: None,
114|        softirq_steal,
115|    })
116|}
117|
118|/// Parse `/proc/stat` aggregate `cpu` line into jiffies (level 3 usage).
119|///
120|/// Line shape: `cpu  user nice system idle iowait irq softirq steal guest guest_nice`
121|pub fn parse_stat(text: &str) -> Option<CpuUsage> {
122|    for line in text.lines() {
123|        let line = line.trim();
124|        if !line.starts_with("cpu ") {
125|            continue;
126|        }
127|        let fields: Vec<u64> = line
128|            .split_whitespace()
129|            .skip(1)
130|            .filter_map(|f| f.parse::<u64>().ok())
131|            .collect();
132|        if fields.len() < 4 {
133|            return None;
134|        }
135|        return Some(CpuUsage {
136|            user: fields[0],
137|            system: fields[2],
138|            idle: fields[3],
139|            iowait: fields.get(4).copied().unwrap_or(0),
140|            softirq: fields.get(6).copied().unwrap_or(0),
141|            steal: fields.get(7).copied().unwrap_or(0),
142|            util_pct: None,
143|        });
144|    }
145|    None
146|}
147|
148|#[cfg(test)]
149|mod tests {
150|    use super::*;
151|
152|    const SAMPLE_CPUINFO: &str = "\
153|processor\t: 0
154|vendor_id\t: AuthenticAMD
155|cpu family\t: 25
156|model\t: 1
157|model name\t: AMD EPYC 7R13
158|stepping\t: 1
159|cpu MHz\t: 2445.360
160|cache size\t: 512 KB
161|physical id\t: 0
162|siblings\t: 2
163|core id\t: 0
164|cpu cores\t: 1
165|...
166|processor\t: 1
167|vendor_id\t: AuthenticAMD
168|model name\t: AMD EPYC 7R13
169|cpu MHz\t: 2445.360
170|cache size\t: 512 KB
171|physical id\t: 0
172|core id\t: 0
173|cpu cores\t: 1
174|";
175|
176|    const SAMPLE_STAT: &str = "\
177|cpu  9432416 1234 3215683 47561286 156789 0 223456 100 0 0
178|intr 123456789
179|ctxt 987654321
180|";
181|
182|    const SAMPLE_PRESSURE: &str = "\
183|some avg10=5.23 avg60=3.14 avg300=1.00 total=9432416
184|full avg10=4.50 avg60=2.00 avg300=0.10 total=123456
185|";
186|
187|    #[test]
188|    fn parse_meminfo_counts_two_logical_cpus() {
189|        let (physical, _, _) = parse_cpuinfo(SAMPLE_CPUINFO);
190|        assert_eq!(physical.model_name, "AMD EPYC 7R13");
191|        assert_eq!(physical.logical_cpus, 2);
192|    }
193|
194|    #[test]
195|    fn parse_stat_extracts_jiffies() {
196|        let usage = parse_stat(SAMPLE_STAT).expect("cpu line parsed");
197|        assert_eq!(usage.user, 9432416);
198|        assert_eq!(usage.system, 3215683);
199|        assert_eq!(usage.idle, 47561286);
200|        assert_eq!(usage.iowait, 156789);
201|        assert_eq!(usage.steal, 100);
202|    }
203|
204|    #[test]
205|    fn parse_pressure_cpu_some_and_total() {
206|        let p = parse_pressure_cpu(SAMPLE_PRESSURE).expect("psi parsed");
207|        assert_eq!(p.some_avg10, Some(5.23));
208|        // /proc/pressure/cpu has no "full" line.
209|        assert_eq!(p.full_avg10, None);
210|        assert_eq!(p.softirq_steal, Some(9432416));
211|    }
